{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "A phosphate-containing polar compound (DHPP-2) showed extremely low brain uptake in rats after oral administration, supporting that ionized phosphorous acid groups limit CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Merck-3, a polar amphiphilic compound with a beta-hydroxy amine and acidic/sulfonamide groups, was a P-gp substrate with brain concentrations below detection after i.v. dosing, supporting poor CNS penetration for similar ionizable molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Vistusertib, a methoxy-substituted aromatic acid/sulfone, had brain distribution less than 5% of plasma in mice, supporting poor BBB permeability for polar ionizable compounds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Fosgonimeton, a phosphate-containing prodrug, was not detected in brain in preclinical studies, supporting that phosphonate/phosphate moieties severely limit brain exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "A carboxylic acid-containing radiotracer showed low brain uptake in rats, supporting that acidic groups reduce CNS access.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query contains a phosphonic acid, a carboxylic acid, and a basic amine, yielding a highly polar, ionizable zwitterion. All transferable experimental evidence from phosphate/phosphonate-containing and polar acidic compounds indicates low or undetectable brain penetration, with no positive CNS-access evidence. Therefore the molecule is predicted to lack meaningful CNS access.",
  "evidence_gaps": [
    "No direct experimental brain/plasma ratio, Kp,uu, or CSF measurement for the exact query molecule.",
    "No data on whether the query is a substrate for brain uptake or efflux transporters.",
    "No prodrug or formulation context is provided that could alter CNS exposure."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

